<?php
declare(strict_types=1);
require __DIR__ . '/includes/db.php';
if(empty($_SESSION['member_id'])){header('Location: /login.php?next=moderation-history.php');exit;}
$memberId=(int)$_SESSION['member_id'];
function mh_h($v):string{return htmlspecialchars((string)($v??''),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$storyReviews=[];$chapterReviews=[];
try{
 $q=$pdo->prepare("SELECT r.id,r.decision,r.note,r.reviewed_at,s.id story_id,s.title story_title,s.slug,s.story_type,s.story_kind FROM story_moderation_reviews r JOIN stories s ON s.id=r.story_id WHERE r.target_type='story' AND s.member_id=? ORDER BY r.reviewed_at DESC,r.id DESC");
 $q->execute([$memberId]);$storyReviews=$q->fetchAll(PDO::FETCH_ASSOC);
 $q=$pdo->prepare("SELECT r.id,r.decision,r.note,r.reviewed_at,s.id story_id,s.title story_title,s.slug,s.story_type,s.story_kind,c.chapter_number,c.title chapter_title FROM story_moderation_reviews r JOIN stories s ON s.id=r.story_id JOIN chapters c ON c.id=r.target_id WHERE r.target_type='chapter' AND s.member_id=? ORDER BY r.reviewed_at DESC,r.id DESC");
 $q->execute([$memberId]);$chapterReviews=$q->fetchAll(PDO::FETCH_ASSOC);
}catch(PDOException $e){http_response_code(500);exit('Chưa cài đặt lịch sử kiểm duyệt. Hãy chạy database/story_moderation_reviews.sql trong phpMyAdmin.');}
$items=[];
foreach($storyReviews as $r){$r['kind']='story';$items[]=$r;}
foreach($chapterReviews as $r){$r['kind']='chapter';$items[]=$r;}
usort($items,static fn($a,$b)=>strcmp((string)$b['reviewed_at'],(string)$a['reviewed_at']));
$approved=count(array_filter($items,static fn($r)=>$r['decision']==='approved'));
$rejected=count($items)-$approved;
?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lịch sử kiểm duyệt | Truyện Đêm</title><link rel="stylesheet" href="/css/style.css"><link rel="stylesheet" href="/css/member-hub.css?v=20261122-light1"><link rel="stylesheet" href="/css/truyenhub-theme.css?v=20261113-1"><link rel="stylesheet" href="/css/site-matte-black.css?v=20261114-matte1"><style>
.mh-stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin:18px 0}.mh-stat{padding:15px;border:1px solid #352d43;border-radius:12px;background:#151520}.mh-stat strong{display:block;font-size:1.45rem;color:#eee}.mh-stat span{font-size:.78rem;color:#a99fb4}.mh-item{padding:16px;border:1px solid #342b40;border-radius:13px;background:#151520;margin:11px 0}.mh-item-head{display:flex;justify-content:space-between;align-items:flex-start;gap:10px}.mh-item h2{font-size:1rem;margin:0 0 6px;color:#f1eafa}.mh-meta{font-size:.76rem;color:#92899f}.mh-note{margin:12px 0 0;padding:11px 13px;border-left:3px solid #9b7ac0;background:#211a2b;border-radius:0 9px 9px 0;color:#d9cbe7;white-space:pre-wrap;overflow-wrap:anywhere}.mh-status{flex-shrink:0;padding:6px 9px;border-radius:20px;font-size:.72rem;font-weight:800}.mh-status.approved{background:#1e382c;color:#bce8ca}.mh-status.rejected{background:#3b2029;color:#ffc4d0}.mh-empty{padding:22px;text-align:center;border:1px dashed #4a3b56;border-radius:12px;color:#a99fb4}
@media(max-width:600px){.mh-stats{gap:7px}.mh-stat{padding:11px 8px}.mh-stat strong{font-size:1.2rem}.mh-stat span{font-size:.69rem}.mh-item{padding:13px}.mh-item-head{flex-direction:column}.mh-status{order:-1}}
</style></head><body class="story-site"><?php require __DIR__ . '/includes/header.php';?><main class="member-hub-main"><section class="member-hub-hero"><span class="kicker">✦ KHU VỰC TÁC GIẢ ✦</span><h1>Lịch sử kiểm duyệt</h1><p>Theo dõi kết quả duyệt truyện, từng chương và góp ý từ đội ngũ Truyện Đêm.</p></section><nav class="member-hub-tabs"><a href="/submit_story.php#my-stories">▤ Bài viết của tôi</a><a href="/notifications.php">♧ Thông báo</a><a href="/moderation-history.php">✓ Lịch sử kiểm duyệt</a><a href="/account.php">Hồ sơ</a></nav><div class="mh-stats"><div class="mh-stat"><strong><?=count($items)?></strong><span>Lượt kiểm duyệt</span></div><div class="mh-stat"><strong><?=$approved?></strong><span>Đã duyệt</span></div><div class="mh-stat"><strong><?=$rejected?></strong><span>Cần chỉnh sửa</span></div></div><section class="member-hub-section"><?php if(!$items):?><div class="mh-empty">Chưa có nội dung nào được kiểm duyệt. Khi đội ngũ xử lý bài gửi, lịch sử sẽ xuất hiện tại đây.</div><?php endif;?><?php foreach($items as $r):?><article class="mh-item"><div class="mh-item-head"><div><h2><?=mh_h($r['kind']==='chapter'?'Chương '.(int)$r['chapter_number'].': '.$r['chapter_title']:$r['story_title'])?></h2><div class="mh-meta"><?=mh_h($r['story_title'])?> · <?=mh_h(date('d/m/Y H:i',strtotime($r['reviewed_at'])))?></div></div><span class="mh-status <?=mh_h($r['decision'])?>"><?=$r['decision']==='approved'?'✓ Đã duyệt':'Cần chỉnh sửa'?></span></div><?php if($r['note']!==''):?><div class="mh-note"><strong>Góp ý kiểm duyệt:</strong><br><?=mh_h($r['note'])?></div><?php endif;?><p><a href="/submit_story.php#my-stories">Mở bài viết của tôi →</a></p></article><?php endforeach;?></section></main><?php require __DIR__ . '/includes/footer.php';?></body></html>